css:
/* Nasty Dingo 81 by Javierrocadev — https://uiverse.io/Javierrocadev/nasty-dingo-81 */
.card {
  display: flex;
  align-items: center;
  justify-content: center;
}

.card * {
  position: absolute;
}

.pentagon1 {
  width: 250px;
  height: 250px;
  background: #03045e;
  clip-path: polygon(50% 0%, 100% 38%, 82% 100%, 18% 100%, 0% 38%);
  transition: all .3s ease-in-out;
}

.pentagon2 {
  width: 220px;
  height: 220px;
  background: #0077b6;
  clip-path: polygon(50% 0%, 100% 38%, 82% 100%, 18% 100%, 0% 38%);
  transition: all .4s ease-in-out;
}

.pentagon3 {
  width: 190px;
  height: 190px;
  background: #00b4d8;
  clip-path: polygon(50% 0%, 100% 38%, 82% 100%, 18% 100%, 0% 38%);
  transition: all .5s ease-in-out;
}

.pentagon4 {
  width: 160px;
  height: 160px;
  background: #90e0ef;
  clip-path: polygon(50% 0%, 100% 38%, 82% 100%, 18% 100%, 0% 38%);
  transition: all .6s ease-in-out;
}

.pentagon5 {
  width: 130px;
  height: 130px;
  background: #caf0f8;
  clip-path: polygon(50% 0%, 100% 38%, 82% 100%, 18% 100%, 0% 38%);
  transition: all .7s ease-in-out;
}

.card:hover .pentagon1, .card:hover .pentagon2 , .card:hover .pentagon3, .card:hover .pentagon4, .card:hover .pentagon5 {
  transform: rotate(35deg);
}
